        grid.append(input[idx])
        idx += 1

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                has_adjacent = False
                # Check four directions
                for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                    ni = i + dx
                    nj = j + dy
                    if 0 <= ni < H and 0 <= nj < W:
                        if grid[ni][nj] == '#':
                            has_adjacent = True
                            break
                if not has_adjacent:
                    print("No")
                    return
    print("Yes")

